<?php
require_once __DIR__ . '/../../includes/bootstrap.php';$user=require_role('hospital_admin');$s=db()->prepare("SELECT id,name FROM organizations WHERE owner_user_id=? AND approval_status='approved' ORDER BY id DESC LIMIT 1");$s->execute([$user['id']]);$org=$s->fetch();if(!$org)redirect('dashboard.php');$oid=(int)$org['id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['appointment_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['confirmed','checked_in','completed','cancelled','no_show'],true))$errors[]='Invalid ticket status.';else{$s=db()->prepare('SELECT a.id,a.patient_user_id,a.starts_at,a.reason,u.email,u.full_name FROM appointments a JOIN users u ON u.id=a.patient_user_id WHERE a.id=? AND a.organization_id=?');$s->execute([$id,$oid]);$a=$s->fetch();if(!$a)$errors[]='Ticket not found for this organization.';else{db()->prepare('UPDATE appointments SET status=? WHERE id=? AND organization_id=?')->execute([$status,$id,$oid]);send_carebridge_email($a['email'],'Appointment ticket updated — CareBridge','Your appointment status has changed','Hello '.$a['full_name'].', your appointment ticket status has been updated by '.$org['name'].'.',['Ticket ID'=>'CB-T'.str_pad((string)$id,6,'0',STR_PAD_LEFT),'New status'=>ucwords(str_replace('_',' ',$status)),'Appointment date'=>date('M j, Y g:i A',strtotime($a['starts_at']))]);flash('success','Ticket CB-T'.str_pad((string)$id,6,'0',STR_PAD_LEFT).' updated.');redirect('hospital/appointments.php');}}}
$filter=(string)($_GET['status']??'all');$valid=['all','requested','confirmed','checked_in','completed','cancelled','no_show'];if(!in_array($filter,$valid,true))$filter='all';$sql="SELECT a.*,u.full_name,u.email,p.patient_code,d.name department_name FROM appointments a JOIN users u ON u.id=a.patient_user_id LEFT JOIN patient_profiles p ON p.user_id=u.id LEFT JOIN departments d ON d.id=a.department_id WHERE a.organization_id=?";$params=[$oid];if($filter!=='all'){$sql.=' AND a.status=?';$params[]=$filter;}$sql.=' ORDER BY CASE a.status WHEN \'requested\' THEN 0 WHEN \'confirmed\' THEN 1 WHEN \'checked_in\' THEN 2 ELSE 3 END,a.starts_at ASC';$s=db()->prepare($sql);$s->execute($params);$items=$s->fetchAll();$pageTitle='Appointments & queue';require __DIR__.'/../../includes/header.php';
?>
<section class="dashboard-welcome"><div><span class="eyebrow">PROVIDER OPERATIONS</span><h1>Appointments & queue</h1><p>Review booking requests and update ticket status. Patients will see changes in their dashboard.</p></div><a class="button button-secondary" href="<?= e(url('hospital/dashboard.php')) ?>">← Dashboard</a></section>
<?php if($errors): ?><div class="alert alert-error"><?php foreach($errors as $e1): ?><?= e($e1) ?><br><?php endforeach; ?></div><?php endif; ?><div class="filter-row"><?php foreach(['all'=>'All tickets','requested'=>'Requested','confirmed'=>'Confirmed','checked_in'=>'Checked in','completed'=>'Completed','cancelled'=>'Cancelled','no_show'=>'No-show'] as $k=>$v): ?><a class="filter-pill <?= $filter===$k?'filter-active':'' ?>" href="<?= e(url('hospital/appointments.php?status='.$k)) ?>"><?= e($v) ?></a><?php endforeach; ?></div>
<div class="table-card"><?php if(!$items): ?><div class="empty-state"><h3>No tickets found</h3><p>Patient booking requests will be listed here.</p></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Ticket / patient</th><th>Visit reason</th><th>Appointment time</th><th>Status</th><th>Update status</th></tr></thead><tbody><?php foreach($items as $a): ?><tr><td><strong>CB-T<?= str_pad((string)$a['id'],6,'0',STR_PAD_LEFT) ?></strong><?= e($a['full_name']) ?><small><?= e($a['patient_code'] ?: $a['email']) ?></small></td><td><?= e($a['reason'] ?: 'General check-up') ?><small><?= e($a['department_name'] ?: 'Unassigned department') ?></small></td><td><?= e(date('M j, Y · g:i A',strtotime($a['starts_at']))) ?></td><td><span class="<?= e(status_class($a['status'])) ?>"><?= e(ucwords(str_replace('_',' ',$a['status']))) ?></span></td><td><form method="post" class="review-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="appointment_id" value="<?= (int)$a['id'] ?>"><select name="status" aria-label="Ticket status"><option value="requested">Requested</option><option value="confirmed" <?= $a['status']==='confirmed'?'selected':'' ?>>Confirmed</option><option value="checked_in" <?= $a['status']==='checked_in'?'selected':'' ?>>Checked in</option><option value="completed" <?= $a['status']==='completed'?'selected':'' ?>>Completed</option><option value="cancelled" <?= $a['status']==='cancelled'?'selected':'' ?>>Cancelled</option><option value="no_show" <?= $a['status']==='no_show'?'selected':'' ?>>No-show</option></select><button class="button button-small" type="submit">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
